import{c as e,Q as n,j as r,m as a}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Defending against Indirect Prompt Injection by Instruction Detection","description":"","frontmatter":{"url":"https://arxiv.org/abs/2505.06311","title":"Defending against Indirect Prompt Injection by Instruction Detection","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2505.06311,"authors":["Tongyu Wen","Chenglong Wang","Xiyuan Yang","Haoyu Tang","Yueqi Xie","Lingjuan Lyu","Zhicheng Dou","Fangzhao Wu"],"pdf_path":"pdfs/2505.06311.pdf","published_date":"2025-05-08T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2025-05-08-indirect-prompt-injection-defense-2505-06311.md","filePath":"research/papers/2025-05-08-indirect-prompt-injection-defense-2505-06311.md","lastUpdated":1785909234000}'),i={name:"research/papers/2025-05-08-indirect-prompt-injection-defense-2505-06311.md"};function o(s,t,c,d,l,g){return n(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="defending-against-indirect-prompt-injection-by-instruction-detection" tabindex="-1">Defending against Indirect Prompt Injection by Instruction Detection <a class="header-anchor" href="#defending-against-indirect-prompt-injection-by-instruction-detection" aria-label="Permalink to &quot;Defending against Indirect Prompt Injection by Instruction Detection&quot;">​</a></h1><p><strong>Authors</strong>: Tongyu Wen, Chenglong Wang, Xiyuan Yang, Haoyu Tang, Yueqi Xie, Lingjuan Lyu, Zhicheng Dou, Fangzhao Wu <strong>Affiliations</strong>: Renmin University of China, Peking University Shenzhen Graduate School, Wuhan University, USTC, HKUST, Sony AI, Microsoft Research Asia <strong>Published</strong>: May 8, 2025 (v1); Revised September 17, 2025 (v2) <strong>Source</strong>: <a href="https://arxiv.org/abs/2505.06311" target="_blank" rel="noreferrer">https://arxiv.org/abs/2505.06311</a><strong>arXiv ID</strong>: 2505.06311 <strong>Categories</strong>: cs.CR, cs.AI <strong>Code</strong>: <a href="https://github.com/MYVAE/Instruction-detection" target="_blank" rel="noreferrer">https://github.com/MYVAE/Instruction-detection</a></p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>The integration of Large Language Models (LLMs) with external sources is becoming increasingly common, with Retrieval-Augmented Generation (RAG) being a prominent example. However, this integration introduces vulnerabilities of Indirect Prompt Injection (IPI) attacks, where hidden instructions embedded in external data can manipulate LLMs into executing unintended or harmful actions. We recognize that IPI attacks fundamentally rely on the presence of instructions embedded within external content, which can alter the behavioral states of LLMs. Can the effective detection of such state changes help us defend against IPI attacks? In this paper, we propose InstructDetector, a novel detection-based approach that leverages the behavioral states of LLMs to identify potential IPI attacks. Specifically, we demonstrate the hidden states and gradients from intermediate layers provide highly discriminative features for instruction detection. By effectively combining these features, InstructDetector achieves a detection accuracy of 99.60% in the in-domain setting and 96.90% in the out-of-domain setting, and reduces the attack success rate to just 0.03% on the BIPIA benchmark. The code is publicly available.</p><hr><h2 id="核心方法" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法" aria-label="Permalink to &quot;核心方法&quot;">​</a></h2><h3 id="instructdetector-架構" tabindex="-1">InstructDetector 架構 <a class="header-anchor" href="#instructdetector-架構" aria-label="Permalink to &quot;InstructDetector 架構&quot;">​</a></h3><p>偵測式防禦（Detection-based defense），在外部資料進入 LLM 前截斷注入指令。三層管線：</p><p><strong>1. Hidden States 提取</strong></p><ul><li>使用 Llama-3.1-8B-Instruct（32 層）作為特徵提取器</li><li>選取第 14 層的最後 token hidden state（實驗驗證效果最佳）</li><li>輸出：4096 維向量</li></ul><p><strong>2. Gradients 提取</strong></p><ul><li>對外部資料配對「Sure」（instruction 典型回應）計算 back-propagation</li><li>聚焦 self-attention 層的梯度（捕捉行為特徵；feed-forward 層偏向知識特徵）</li><li>應用 max-pooling 降維 → 400,000 維向量</li></ul><p><strong>3. Feature Fusion + MLP 分類器</strong></p><ul><li>線性變換對齊兩種特徵維度 → 正規化 → 拼接</li><li>MLP 分類器（隱藏層：1024, 256, 64, 16）</li><li>訓練集：200 樣本（100 正/100 負），平衡設計</li></ul><h3 id="資料集組合" tabindex="-1">資料集組合 <a class="header-anchor" href="#資料集組合" aria-label="Permalink to &quot;資料集組合&quot;">​</a></h3><ul><li><strong>外部資料（負樣本來源）</strong>：Wikipedia、News Articles</li><li><strong>指令資料（正樣本來源）</strong>：LaMini-instruction、BIPIA</li><li><strong>評估組合</strong>：4 種 2,000 樣本組合，最高 OOD 難度 = News Articles + BIPIA</li></ul><hr><h2 id="關鍵數字" tabindex="-1">關鍵數字 <a class="header-anchor" href="#關鍵數字" aria-label="Permalink to &quot;關鍵數字&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指標</th><th>數值</th></tr></thead><tbody><tr><td>偵測準確率（In-domain）</td><td><strong>99.60%</strong></td></tr><tr><td>偵測準確率（Out-of-domain）</td><td><strong>96.90%</strong></td></tr><tr><td>Attack Success Rate（BIPIA benchmark）</td><td><strong>0.03%</strong></td></tr><tr><td>訓練樣本數</td><td>200（100+/100-）</td></tr><tr><td>特徵提取模型</td><td>Llama-3.1-8B-Instruct（32 層）</td></tr><tr><td>最佳層位</td><td>第 14 層（hidden states + gradients 均確認）</td></tr></tbody></table><p><strong>比較基準</strong>（BIPIA benchmark 上 ASR 對比）：</p><ul><li>Prevention-based methods（如 adversarial training）：仍有明顯 ASR</li><li>InstructDetector：0.03%，超越所有 prevention-based 方法</li></ul><p><strong>測試模型覆蓋</strong>：Vicuna-7B、Qwen2.5-7B-Instruct（開源）；GPT-3.5-Turbo、GPT-4o（閉源）</p><hr><h2 id="對-prompt-caching-management-engineering-的關聯" tabindex="-1">對 Prompt Caching / Management / Engineering 的關聯 <a class="header-anchor" href="#對-prompt-caching-management-engineering-的關聯" aria-label="Permalink to &quot;對 Prompt Caching / Management / Engineering 的關聯&quot;">​</a></h2><h3 id="prompt-caching" tabindex="-1">Prompt Caching <a class="header-anchor" href="#prompt-caching" aria-label="Permalink to &quot;Prompt Caching&quot;">​</a></h3><ul><li><strong>IPI 對快取的威脅</strong>：RAG 系統中被快取的 system prompt 若包含外部資料，攻擊者可透過 IPI 讓快取的「安全」前綴失效，讓後續 request 執行惡意指令</li><li><strong>InstructDetector 作為前置閘門</strong>：在外部資料觸達快取 prefix 之前先執行偵測，保護 prompt cache 不被污染；偵測成本（小型 MLP 分類）低於 LLM forward pass</li></ul><h3 id="prompt-management" tabindex="-1">Prompt Management <a class="header-anchor" href="#prompt-management" aria-label="Permalink to &quot;Prompt Management&quot;">​</a></h3><ul><li><strong>External Content 分級管理</strong>：本文的偵測框架提示 prompt 管理策略應對外部資料來源做信任分級（Wikipedia vs. 用戶上傳 vs. 爬取資料），高風險來源先過 InstructDetector</li><li><strong>RAG Pipeline 安全閘</strong>：偵測模型應插入 retrieval 之後、generation 之前，形成 retrieval → detect → generate 的安全管線</li></ul><h3 id="prompt-engineering" tabindex="-1">Prompt Engineering <a class="header-anchor" href="#prompt-engineering" aria-label="Permalink to &quot;Prompt Engineering&quot;">​</a></h3><ul><li><strong>IPI 攻擊面認知</strong>：Prompt engineer 設計 RAG system prompt 時需考慮：若外部 chunk 含有 &quot;Modify your response to...&quot; 類指令，系統會被操控（真實案例：peer review 系統被隱藏指令操控）</li><li><strong>防禦設計選擇</strong>：Prevention（修改 prompt 讓 LLM 忽略外部指令）vs. Detection（InstructDetector）——本文主張偵測式更能保護良性推論不被干擾，且不需修改 system prompt</li><li><strong>訓練效率</strong>：僅需 200 樣本即可訓練有效偵測器，對 prompt engineering 實踐中快速部署防禦具參考價值</li></ul>',31)])])}const u=e(i,[["render",o]]);export{p as __pageData,u as default};
